import os
from dataclasses import dataclass
from typing import Any, Dict, Optional
from urllib.parse import urlencode, urljoin

import requests


class FederatedLoginError(Exception):
    pass


def _normalize_claims(claims: Dict[str, Any]) -> Dict[str, Any]:
    def pick(*keys: str) -> Any:
        for key in keys:
            value = claims.get(key)
            if value is not None and value != "":
                return value
        return None

    normalized = {
        "subject": pick("sub", "user_id", "id"),
        "email": pick("email", "mail", "preferred_username", "upn"),
        "email_verified": bool(claims.get("email_verified")) if claims.get("email_verified") is not None else None,
        "name": pick("name", "display_name", "given_name"),
        "given_name": pick("given_name", "first_name"),
        "family_name": pick("family_name", "last_name"),
        "picture": pick("picture", "avatar_url", "profile_picture"),
        "locale": pick("locale", "language"),
        "issuer": pick("iss", "issuer"),
        "audience": pick("aud", "client_id", "audience"),
        "raw": claims,
    }

    # Preserve any useful additional claims in a normalized "attributes" map.
    reserved = {
        "sub", "user_id", "id", "email", "mail", "preferred_username", "upn",
        "email_verified", "name", "display_name", "given_name", "first_name",
        "family_name", "last_name", "picture", "avatar_url", "profile_picture",
        "locale", "language", "iss", "issuer", "aud", "client_id", "audience",
    }
    attributes = {k: v for k, v in claims.items() if k not in reserved}
    normalized["attributes"] = attributes
    return normalized


@dataclass
class MicrosoftEntraOIDCClient:
    tenant_id: str
    client_id: str
    client_secret: Optional[str] = None
    redirect_uri: Optional[str] = None
    scope: str = "openid profile email"
    authority_host: str = "https://login.microsoftonline.com"
    session: requests.Session = requests.Session()

    @property
    def issuer(self) -> str:
        return f"{self.authority_host.rstrip('/')}/{self.tenant_id}/v2.0"

    @property
    def authorize_endpoint(self) -> str:
        return f"{self.issuer}/authorize"

    @property
    def token_endpoint(self) -> str:
        return f"{self.issuer}/oauth2/v2.0/token"

    @property
    def userinfo_endpoint(self) -> str:
        return f"{self.issuer}/openid/userinfo"

    def get_authorization_request_url(self, state: str, nonce: Optional[str] = None, prompt: Optional[str] = None) -> str:
        if not self.redirect_uri:
            raise FederatedLoginError("redirect_uri is required to build the authorization request URL.")

        params = {
            "client_id": self.client_id,
            "response_type": "code",
            "redirect_uri": self.redirect_uri,
            "response_mode": "query",
            "scope": self.scope,
            "state": state,
        }
        if nonce:
            params["nonce"] = nonce
        if prompt:
            params["prompt"] = prompt
        return f"{self.authorize_endpoint}?{urlencode(params)}"

    def acquire_token_by_authorization_code(self, code: str) -> Dict[str, Any]:
        if not self.redirect_uri:
            raise FederatedLoginError("redirect_uri is required to exchange an authorization code.")
        if not self.client_secret:
            raise FederatedLoginError("client_secret is required to exchange an authorization code.")

        data = {
            "client_id": self.client_id,
            "scope": self.scope,
            "code": code,
            "redirect_uri": self.redirect_uri,
            "grant_type": "authorization_code",
            "client_secret": self.client_secret,
        }
        resp = self.session.post(self.token_endpoint, data=data, timeout=30)
        if resp.status_code >= 400:
            raise FederatedLoginError(f"Token exchange failed: {resp.status_code} {resp.text}")
        return resp.json()

    def fetch_userinfo(self, access_token: str) -> Dict[str, Any]:
        headers = {"Authorization": f"Bearer {access_token}"}
        resp = self.session.get(self.userinfo_endpoint, headers=headers, timeout=30)
        if resp.status_code >= 400:
            raise FederatedLoginError(f"Userinfo request failed: {resp.status_code} {resp.text}")
        return resp.json()

    def fetch_and_normalize_profile_claims(
        self,
        code: Optional[str] = None,
        access_token: Optional[str] = None,
    ) -> Dict[str, Any]:
        if access_token is None:
            if code is None:
                raise FederatedLoginError("Either access_token or code must be provided.")
            token_response = self.acquire_token_by_authorization_code(code)
            access_token = token_response.get("access_token")
            if not access_token:
                raise FederatedLoginError("Token response did not include an access_token.")

        claims = self.fetch_userinfo(access_token)
        return _normalize_claims(claims)


def fetch_federated_user_profile_claims(
    code: Optional[str] = None,
    access_token: Optional[str] = None,
    tenant_id: Optional[str] = None,
    client_id: Optional[str] = None,
    client_secret: Optional[str] = None,
    redirect_uri: Optional[str] = None,
) -> Dict[str, Any]:
    tenant_id = tenant_id or os.environ.get("AZURE_TENANT_ID")
    client_id = client_id or os.environ.get("AZURE_CLIENT_ID")
    client_secret = client_secret or os.environ.get("AZURE_CLIENT_SECRET")
    redirect_uri = redirect_uri or os.environ.get("AZURE_REDIRECT_URI")

    if not tenant_id:
        raise FederatedLoginError("AZURE_TENANT_ID is required.")
    if not client_id:
        raise FederatedLoginError("AZURE_CLIENT_ID is required.")

    client = MicrosoftEntraOIDCClient(
        tenant_id=tenant_id,
        client_id=client_id,
        client_secret=client_secret,
        redirect_uri=redirect_uri,
    )
    return client.fetch_and_normalize_profile_claims(code=code, access_token=access_token)
